recipes.code:
{
  "inputs": [
    {
      "id": "seerxo-api-key",
      "type": "promptString",
      "description": "Optional API key from seerxo.com — omit to use the free tier set up via 'seerxo configure'.",
      "password": true
    }
  ],
  "servers": {
    "seerxo": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "seerxo@1.13.0"
      ],
      "env": {
        "SEERXO_EMAIL": "<seerxo-email>",
        "SEERXO_API_KEY": "${input:seerxo-api-key}"
      }
    }
  }
}
